<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Pencil, Trash2, Send, Clock3 } from 'lucide-vue-next'
import RichEditor from './RichEditor.vue'
import { request, send } from './api'
import { variables, presets, sampleValues, placeholders, substitute, plainDoc } from '../../shared/messages'
type Mode='templates'|'messages'; const props=defineProps<{mode:Mode}>()
const templates=ref<any[]>([]),messages=ref<any[]>([]),exams=ref<any[]>([]),search=ref(''),step=ref(1),tab=ref('normal')
const templateOpen=ref(false),wizardOpen=ref(false),confirmOpen=ref(false),previewText=ref('')
const templateEditor=ref<any>(),messageEditor=ref<any>(),templateWildcard=ref(''),messageWildcard=ref(''),filter=reactive({sendType:''})
const form=reactive<any>({id:'',name:'',status:'draft',title:'',content:'',document:plainDoc(''),variables:[]})
const draft=reactive<any>({id:'',sendType:'manual',status:'draft',title:'',content:'',document:plainDoc(''),templateId:null,systemKey:'',channels:['h5'],categoryIds:[],examIds:[],permissionLevels:[],schedule:{}})
const permissions=[{id:'free',name:'免费用户'},{id:'vip',name:'VIP'},{id:'svip',name:'SVIP'}], l1=[{id:'social-work',name:'社会工作'}]
const normalMessages=computed(()=>messages.value.filter(x=>(!search.value||String(x.title||'').includes(search.value))&&(!filter.sendType||x.send_type===filter.sendType)))
function text(n:any):string{return !n?'':typeof n.text==='string'?n.text:Array.isArray(n.content)?n.content.map(text).join(''):''}
async function load(){templates.value=await request('/admin/message-templates');messages.value=await request('/admin/messages');exams.value=await request('/exams')};onMounted(load)
function newTemplate(){Object.assign(form,{id:crypto.randomUUID(),name:'',status:'draft',title:'',content:'',document:plainDoc(''),variables:[]});templateOpen.value=true}
function editTemplate(r:any){Object.assign(form,{...r,document:r.document||plainDoc(r.content||'')});templateOpen.value=true}
async function saveTemplate(){if(!form.name.trim()||!form.title.trim()||!form.content.trim())return ElMessage.warning('请填写模板名称、消息标题和正文');form.variables=placeholders(form.title+'\n'+form.content);await send('/admin/message-templates/'+form.id,form,'PUT');templateOpen.value=false;ElMessage.success('消息模板已保存');load()}
function insert(kind:string){const v=kind.startsWith('template')?templateWildcard.value:messageWildcard.value;if(!v)return;if(kind==='templateTitle')form.title+=v;if(kind==='messageTitle')draft.title+=v;if(kind==='templateBody')templateEditor.value?.insertText(v);if(kind==='messageBody')messageEditor.value?.insertText(v);if(kind.startsWith('template'))templateWildcard.value='';else messageWildcard.value=''}
function applyTemplate(t:any){if(!t)return;draft.templateId=t.id;draft.title=t.title;draft.content=t.content||'';draft.document=t.document||plainDoc(t.content||'')}
function applyPreset(p:any){draft.systemKey=p.key;draft.title=p.title;draft.content=p.body;draft.document=plainDoc(p.body)}
function newMessage(){Object.assign(draft,{id:crypto.randomUUID(),sendType:'manual',status:'draft',title:'',content:'',document:plainDoc(''),templateId:null,systemKey:'',channels:['h5'],categoryIds:[],examIds:[],permissionLevels:[],schedule:{frequency:'weekly',weekday:1,time:'09:00'}});step.value=1;wizardOpen.value=true}
function editMessage(r:any){Object.assign(draft,{...r,permissionLevels:r.permission_levels||[],examIds:r.exam_ids||[],categoryIds:r.category_ids||[],schedule:r.schedule||{}});step.value=2;wizardOpen.value=true}
function editSystem(p:any){newMessage();draft.systemKey=p.key;draft.sendType='scheduled';applyPreset(p);step.value=2}
function next(){if(step.value===1){step.value=2;return}if(step.value===2){if(!draft.permissionLevels.length)return ElMessage.warning('请选择会员权限');if(!draft.title.trim()||!draft.content.trim())return ElMessage.warning('请填写消息标题和正文');previewText.value=substitute(draft.title+'\n\n'+draft.content,sampleValues);step.value=3}}
async function saveDraft(){await send('/admin/messages',draft,'POST');wizardOpen.value=false;ElMessage.success('消息已暂存');load()}
async function finalSend(){await ElMessageBox.confirm(draft.sendType==='scheduled'?'确认执行这个发送计划吗？':'确认立即发送这条消息吗？','最终确认',{type:'warning',confirmButtonText:draft.sendType==='scheduled'?'定时发送':'立即发送',cancelButtonText:'返回'});await send('/admin/messages',draft,'POST');if(draft.sendType==='manual'&&!draft.schedule?.enabled)await send('/admin/messages/'+draft.id+'/send',{});wizardOpen.value=false;ElMessage.success('操作成功');load()}
async function remove(r:any){try{await ElMessageBox.confirm('删除后无法恢复，确定删除吗？','严重操作确认',{type:'warning'});await send('/admin/messages/'+r.id,{},'DELETE');load()}catch{}}
async function sendRow(r:any){try{await ElMessageBox.confirm('确认立即发送这条消息吗？','发送确认',{type:'warning',confirmButtonText:'立即发送'});await send('/admin/messages/'+r.id+'/send',{force:true});load()}catch{}}
function fmt(v:any){return v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'}
function sendTypeLabel(v:string){return v==='manual'?'手动发送':v==='scheduled'?'计划发送':'暂存'}
defineExpose({newItem:()=>props.mode==='templates'?newTemplate():newMessage()})
</script>
<template>
<section class="messages-page">
<template v-if="props.mode==='templates'"><div class="list-card"><div class="list-toolbar">全部模板 <b>{{templates.length}}</b></div><table><thead><tr><th>模板名称</th><th>消息标题</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in templates" :key="r.id"><td>{{r.name}}</td><td>{{r.title}}</td><td>{{r.status}}</td><td><button class="icon-link" @click="editTemplate(r)"><Pencil :size="15"/>编辑</button></td></tr></tbody></table></div></template>
<template v-else><el-tabs v-model="tab" class="message-tabs"><el-tab-pane label="普通消息" name="normal"><div class="list-card"><div class="list-toolbar"><el-input v-model="search" placeholder="搜索消息标题" clearable/><el-select v-model="filter.sendType" placeholder="发送类型" clearable><el-option label="全部" value="" /><el-option label="手动发送" value="manual"/><el-option label="计划发送" value="scheduled"/><el-option label="暂存" value="draft"/></el-select></div><table><thead><tr><th>消息标题</th><th>展示端</th><th>考试项目</th><th>会员权限</th><th>发送类型</th><th>发布时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in normalMessages" :key="r.id"><td>{{r.title}}</td><td>{{(r.channels||[]).join('、')}}</td><td>{{r.exam_ids?.length?r.exam_ids.join('、'):'全部考试'}}</td><td>{{r.permission_levels?.join('、')}}</td><td>{{sendTypeLabel(r.send_type)}}</td><td>{{fmt(r.sent_at||r.created_at)}}</td><td><button class="icon-link" @click="editMessage(r)"><Pencil :size="14"/>编辑</button><button class="icon-link danger" @click="remove(r)"><Trash2 :size="14"/>删除</button><button v-if="r.status!=='active'" class="icon-link" @click="sendRow(r)"><Send :size="14"/>发送</button></td></tr></tbody></table></div></el-tab-pane><el-tab-pane label="系统消息" name="system"><div class="list-card"><div class="list-toolbar">系统消息 <b>{{presets.length}}</b><span class="muted">触发条件由系统维护，内容可以编辑</span></div><table><thead><tr><th>消息名称</th><th>触发说明</th><th>默认标题</th><th>操作</th></tr></thead><tbody><tr v-for="p in presets" :key="p.key"><td>{{p.name}}</td><td>{{p.help}}</td><td>{{p.title}}</td><td><button class="icon-link" @click="editSystem(p)"><Pencil :size="14"/>编辑内容</button></td></tr></tbody></table></div></el-tab-pane></el-tabs></template>
</section>
<el-drawer v-model="templateOpen" title="编辑消息模板" direction="rtl" size="720px"><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="已发布" value="published"/><el-option label="已下架" value="offline"/></el-select></el-form-item><el-form-item label="消息标题" required><div class="var-row title-row"><el-input v-model="form.title"/><el-select v-model="templateWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('templateTitle')">插入到标题</el-button></div></el-form-item><el-form-item label="正文" required><div class="var-row"><el-select v-model="templateWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('templateBody')">插入到正文</el-button></div><RichEditor ref="templateEditor" :model-value="form.document" :plain-text="form.content" :content-id="form.id" :allow-media="false" :allow-handouts="false" @update:model-value="(d:any)=>{form.document=d;form.content=text(d).trim()}"/></el-form-item></el-form><template #footer><el-button @click="templateOpen=false">取消</el-button><el-button type="primary" @click="saveTemplate">保存模板</el-button></template></el-drawer>
<el-drawer v-model="wizardOpen" :title="step===1?'新建消息':draft.systemKey?'编辑系统消息':draft.sendType==='scheduled'?'编辑计划消息':'编辑手动消息'" direction="rtl" size="820px"><div class="wizard-step"><span :class="{active:step===1}">1 选择发送方式</span><i></i><span :class="{active:step===2}">2 编辑内容与范围</span><i></i><span :class="{active:step===3}">3 预览确认</span></div><template v-if="step===1"><div class="send-choice"><button :class="{selected:draft.sendType==='manual'}" @click="draft.sendType='manual'"><strong>手动发送</strong><span>运营公告、活动通知</span></button><button :class="{selected:draft.sendType==='scheduled'}" @click="draft.sendType='scheduled'"><strong>计划发送</strong><span>按周期自动发送</span></button></div></template><template v-else-if="step===2"><el-form label-position="top"><el-form-item label="展示端"><el-checkbox-group v-model="draft.channels"><el-checkbox label="h5">H5</el-checkbox><el-checkbox label="miniapp" disabled>小程序</el-checkbox><el-checkbox label="app" disabled>APP</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="消息标题" required><div class="var-row title-row"><el-input v-model="draft.title"/><el-select v-model="messageWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('messageTitle')">插入到标题</el-button></div></el-form-item><div class="scope-row"><el-form-item label="考试项目分类"><el-select v-model="draft.categoryIds" multiple collapse-tags placeholder="全部分类" @change="v=>{if(!v.length)draft.examIds=[]}"><el-option v-for="c in l1" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="考试项目"><el-select v-model="draft.examIds" multiple collapse-tags placeholder="全部考试" :disabled="!draft.categoryIds.length"><el-option v-for="e in exams" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item></div><el-form-item label="会员权限（必选）"><el-checkbox-group v-model="draft.permissionLevels"><el-checkbox v-for="p in permissions" :key="p.id" :label="p.id">{{p.name}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="正文" required><div class="var-row"><el-select v-model="messageWildcard" placeholder="选择通配符" clearable><el-option v-for="v in variables" :key="v.key" :label="v.label" :value="'{{'+v.key+'}}'"/></el-select><el-button @click="insert('messageBody')">插入到正文</el-button></div><RichEditor ref="messageEditor" :model-value="draft.document" :plain-text="draft.content" :content-id="draft.id" :allow-media="false" :allow-handouts="false" @update:model-value="(d:any)=>{draft.document=d;draft.content=text(d).trim()}"/></el-form-item><el-form-item label="选择消息模板（可选）"><el-select clearable placeholder="不使用模板" @change="(id:string)=>applyTemplate(templates.find(t=>t.id===id))"><el-option v-for="t in templates" :key="t.id" :label="t.name" :value="t.id"/></el-select></el-form-item><el-form-item v-if="draft.sendType==='manual'" label="定时发送"><div class="schedule-row"><el-switch v-model="draft.schedule.enabled"/><el-date-picker v-if="draft.schedule.enabled" v-model="draft.schedule.scheduledAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></div></el-form-item></el-form></template><template v-else><div class="preview-pane"><span class="preview-label">H5 用户端预览</span><h2>{{previewText.split('\n\n')[0]}}</h2><p>{{previewText.split('\n\n').slice(1).join('\n\n')}}</p><small>通配符已使用示例数据替换</small></div></template><template #footer><el-button @click="wizardOpen=false">取消</el-button><el-button v-if="step>1" @click="step--">上一步</el-button><el-button v-if="step===2" @click="saveDraft">暂存</el-button><el-button v-if="step===2" @click="next">下一步</el-button><el-button v-if="step===1" type="primary" @click="next">下一步</el-button><el-button v-if="step===3" @click="saveDraft">暂存</el-button><el-button v-if="step===3" type="primary" @click="finalSend">{{draft.sendType==='scheduled'?'定时发送':'立即发送'}}</el-button></template></el-drawer>
</template>
<style scoped>.messages-page{padding:4px 0 40px}.list-card{border:1px solid #e1e8f0;border-radius:11px;background:#fff;overflow:auto;margin-bottom:18px}.list-toolbar{display:flex;gap:10px;align-items:center;padding:15px 18px;border-bottom:1px solid #e8eef4}.list-toolbar .el-input{width:220px}.list-toolbar .el-select{width:150px}.muted{margin-left:auto;color:#8b9bae;font-size:12px}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;padding:12px 16px;background:#f8fafc;color:#70839a}td{padding:14px 16px;border-top:1px solid #edf1f5;color:#53677e}.icon-link{display:inline-flex;align-items:center;gap:4px;border:0;background:none;color:#3569e8;padding:3px 5px;cursor:pointer}.danger{color:#dd5a5a}.var-row{display:flex;gap:8px}.var-row .el-input{flex:1}.var-row .el-select{width:230px}.scope-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.schedule-row{display:flex;align-items:center;gap:24px}.send-choice{display:grid;grid-template-columns:1fr 1fr;gap:14px}.send-choice button{padding:20px;text-align:left;background:#fff;border:1px solid #d9e3ef;border-radius:10px}.send-choice button.selected{border-color:#3569e8;background:#f3f7ff}.wizard-step{display:flex;gap:12px;margin-bottom:22px}.wizard-step .active{color:#3569e8;font-weight:700}.preview-pane{padding:24px;border:1px solid #dfe8f2;border-radius:12px;background:#f7faff}.preview-pane h2{margin:16px 0 10px;color:#203957}.preview-pane p{white-space:pre-line;line-height:1.8;color:#526a84}.preview-pane small{color:#98a6b5}.message-tabs :deep(.el-tabs__nav-wrap:after){background:#e8edf3}.message-tabs :deep(.el-tabs__item){height:42px;padding:0 22px;font-weight:600}.message-tabs :deep(.el-tabs__active-bar){height:3px;border-radius:3px}@media(max-width:900px){.scope-row{grid-template-columns:1fr}.var-row{flex-wrap:wrap}.var-row .el-select{width:100%}}</style>

